<script>
 import {resourceDisposition} from '../../../server/resource-disposition.js';
 const assessedAt=new Date().toISOString();
 let {record={},resources=[],observations=[],evidence=[]}=$props();
 function sourceName(id){return evidence.find(source=>source.id===id)?.title||'Source reference unavailable';}
</script>
{#if record.requirements?.length || resources.length || observations.length}
<details class="evidence-constraints"><summary>Evidence and constraints</summary>
 {#if record.requirements?.length}<h4>Route requirements</h4><ul>{#each record.requirements as requirement,index(index)}<li>{requirement}</li>{/each}</ul>{/if}
 {#if observations.length}<h4>Reported observations</h4>{#each observations as observation(observation.id)}<article><p><strong>{observation.metric}</strong>: {observation.value===null?'Unknown':observation.value} {observation.value===null?'':observation.unit}</p><small>{observation.state||'user-reported'} · Observed {observation.observedAt||'time unknown'}</small><p class="source">{sourceName(observation.evidenceId)}</p></article>{/each}{/if}
 {#each resources as resource(resource.id)}{@const disposition=resourceDisposition(resource,assessedAt)}<article><h4>Resource constraints · {disposition.label}</h4>{#if resource.confirmation}<p>Manager-reported use: {resource.confirmation.purpose}</p><small>Recorded {resource.confirmation.recordedAt} · revision {resource.confirmation.revision} · by {resource.confirmation.actorId}</small><p>Reported window: {resource.confirmation.start||'unknown'} → {resource.confirmation.end||'unknown'} · {resource.confirmation.timeZone||'unknown'}</p>{#if resource.confirmation.notes}<p>{resource.confirmation.notes}</p>{/if}{/if}<small>Planning check as of {disposition.asOf}. Based on the details shown below; this does not change the saved record or approve a booking.</small>{#if disposition.reasons.length}<ul>{#each disposition.reasons as reason(reason)}<li>{reason}</li>{/each}</ul>{:else}<p>The recorded details meet this planning check. Reconfirm permission and availability for the intended use before acting.</p>{/if}<p>{resource.capabilities?.length?resource.capabilities.join(' · '):'Capabilities unknown'} · {resource.location||'Location unknown'}</p><p><strong>Availability:</strong> {resource.availability?.status||'unknown'}</p>{#if resource.availability?.start||resource.availability?.end}<p>{resource.availability.start||'Start unknown'} → {resource.availability.end||'End unknown'} · {resource.availability.timeZone||'Time zone unknown'}</p>{/if}{#if resource.availability?.notes}<p>{resource.availability.notes}</p>{/if}<p><strong>Rights:</strong> {resource.rights?.status||'unverified'}</p>{#if resource.rights?.notes}<p>{resource.rights.notes}</p>{/if}{#each resource.rights?.evidenceIds||[] as id(id)}<p class="source">Rights reference: {sourceName(id)}</p>{/each}<small>Check current availability and permission for the proposed use before acting.</small></article>{/each}
</details>
{/if}
<style>
.evidence-constraints{margin:12px 0;font-size:13px;line-height:1.5}.evidence-constraints summary{cursor:pointer;font-weight:600}.evidence-constraints h4{margin:10px 0 4px}.evidence-constraints p{margin:4px 0;white-space:pre-wrap;overflow-wrap:anywhere}.evidence-constraints article{padding:6px 0}.evidence-constraints small,.source{color:var(--muted,#69765f)}
</style>
